package com.bobfull.chat.controller;
import static org.mockito.Mockito.*;
import com.bobfull.chat.dto.*; import com.bobfull.chat.security.StompPrincipal; import com.bobfull.chat.service.ChatMessageCommandService; import com.bobfull.common.exception.*; import com.bobfull.common.security.*; import java.time.Instant; import org.junit.jupiter.api.Test; import org.springframework.messaging.simp.SimpMessagingTemplate;
class ChatMessageControllerTest {
 @Test void 저장_Service가_성공한_후_채팅방_destination으로_한번_발행한다(){ChatMessageCommandService service=mock(ChatMessageCommandService.class);SimpMessagingTemplate template=mock(SimpMessagingTemplate.class);ChatMessageController c=new ChatMessageController(service,template);var response=new ChatMessageSentResponse(1L,3L,7L,8L,"회원","안녕", Instant.now());when(service.send(3L,new AuthMember(7L,MemberRole.MEMBER),"안녕")).thenReturn(response);c.send(3L,new ChatMessageSendRequest("안녕"),new StompPrincipal(new AuthMember(7L,MemberRole.MEMBER)));verify(template).convertAndSend("/sub/chat/rooms/3",response);}
 @Test void 저장_Service가_실패하면_발행하지_않는다(){ChatMessageCommandService service=mock(ChatMessageCommandService.class);SimpMessagingTemplate template=mock(SimpMessagingTemplate.class);ChatMessageController c=new ChatMessageController(service,template);when(service.send(anyLong(),any(),any())).thenThrow(new CustomException(CommonErrorCode.INVALID_INPUT_VALUE));org.assertj.core.api.Assertions.assertThatThrownBy(()->c.send(3L,new ChatMessageSendRequest(""),new StompPrincipal(new AuthMember(7L,MemberRole.MEMBER)))).isInstanceOf(CustomException.class);verifyNoInteractions(template);}
}
